select * from jsonb_populate_recordset(null::public.transcripts, $aangan$[{"id":"6111e5b3-c0a1-4b14-9129-0ebd13473de3","enquiry_id":"672d1747-3235-4442-a98a-9bea4eda1e44","source":"audio","audio_url":null,"raw_text":"Front Desk: Good morning, Aangan Studio.\nCaller: Hi, I’m Priya. I got your number from a friend — Shruti Joshi. She had her flat done by you in Aundh.\nFront Desk: Of course — thank you for calling. What are you looking to do?\nCaller: We have a 3BHK in Kothrud — Dahanukar Colony. We bought it two years ago and it still looks like the builder flat. We want to redo the whole thing — kitchen, living room, both bedrooms.\nFront Desk: That sounds like a complete redesign. How big is the apartment?\nCaller: About 1,400 sq ft carpet.\nFront Desk: And your timeline?\nCaller: We’d like to be done by March. We’re in no rush.\nFront Desk: Perfect. Are you the owner?\nCaller: Yes — myself and my husband. He knows we’re calling and is happy to go ahead.\nFront Desk: Lovely. Can I take your number and schedule a consultation?\nCaller: Sure. (gives number)","processed_text":null,"language":"en","duration_seconds":252,"transcription_confidence":0.97,"field_confidence":{},"ambiguity_flags":[],"extraction":{"client_name":"Priya","client_phone":"[redacted in source]","client_email":null,"intent":"new_project","project_type":"residential","scope_type":"full_home","scope_summary":"Full redesign of a 3BHK: kitchen, living room and both bedrooms.","scope_clarity":"clear","location":"Kothrud (Dahanukar Colony), Pune","location_clarity":"clear","in_service_area":true,"area_sqft":1400,"style_preferences":[],"timeline_text":"Done by March; no rush.","weeks_to_completion":26,"budget_low_inr":null,"budget_high_inr":null,"budget_flexibility":"unknown","referral_source":"Shruti Joshi (past client, Aundh)","founder_connection":false,"asked_for_pricing":false,"competitive":false,"custom_work_flags":[],"criteria":{"real_project":"pass","service_area":"pass","timeline":"pass","budget":"unclear","decision_maker":"pass"},"criteria_notes":{},"clarifying_question":null,"summary":"Owner (with husband’s consent) of a 3BHK in Kothrud wants a full redesign — kitchen, living room, both bedrooms — about 1,400 sq ft carpet, finished by March. Referred by past client Shruti Joshi. Consultation to be scheduled.","sentiment":"positive","ambiguity_flags":[],"field_confidence":{},"transcription_confidence":0.97,"inaudible_count":0},"model":"gemini-3.8-flash","input_tokens":1111,"output_tokens":750,"ai_cost_inr":0.8746,"created_at":"2026-09-02T04:54:00.000Z"},{"id":"6b3a128e-716a-40f9-b740-451ebc718547","enquiry_id":"9eeb612e-572e-4e3b-95f1-b45f30a3cab2","source":"audio","audio_url":null,"raw_text":"Front Desk: Good afternoon, Aangan Studio.\nCaller: Hi. I was looking at your work on Instagram. I have a 2BHK in Wakad — can you tell me roughly how much something like that would cost?\nFront Desk: Our pricing depends on the materials and the scope — the best way to get a clear picture is a consultation with one of our designers, who can walk you through everything. What are you planning to do?\nCaller: Full redesign — modular kitchen, wardrobes, living room, both bedrooms. About 950 sq ft.\nFront Desk: Good scope. What’s your timeline?\nCaller: We move in November — so maybe starting design from October?\nFront Desk: That works well. Shall I set up a consultation?\nCaller: Yes, but can you give me a rough ballpark first? Even a range?\nFront Desk: I genuinely can’t — it varies quite a bit based on materials. Giving you a number without seeing the site would be misleading. The designer will go through all of that with you — the consultation is free and there’s no obligation.\nCaller: Okay, fair enough. Let’s book it.","processed_text":null,"language":"en","duration_seconds":308,"transcription_confidence":0.96,"field_confidence":{},"ambiguity_flags":[],"extraction":{"client_name":null,"client_phone":"[redacted in source]","client_email":null,"intent":"new_project","project_type":"residential","scope_type":"full_home","scope_summary":"Full redesign of a 2BHK: modular kitchen, wardrobes, living room, both bedrooms.","scope_clarity":"clear","location":"Wakad, Pune","location_clarity":"clear","in_service_area":true,"area_sqft":950,"style_preferences":[],"timeline_text":"Moving in November; wants design to start in October.","weeks_to_completion":9,"budget_low_inr":null,"budget_high_inr":null,"budget_flexibility":"unknown","referral_source":null,"founder_connection":false,"asked_for_pricing":true,"competitive":false,"custom_work_flags":[],"criteria":{"real_project":"pass","service_area":"pass","timeline":"pass","budget":"unclear","decision_maker":"unclear"},"criteria_notes":{},"clarifying_question":null,"summary":"2BHK in Wakad (~950 sq ft), full redesign incl. modular kitchen and wardrobes, moving in November so design should start in October. Asked twice for a price range and was correctly deflected; accepted a free consultation. Name not captured.","sentiment":"neutral","ambiguity_flags":[],"field_confidence":{},"transcription_confidence":0.96,"inaudible_count":0},"model":"gemini-3.8-flash","input_tokens":1157,"output_tokens":750,"ai_cost_inr":1.0323,"created_at":"2026-09-03T09:12:00.000Z"},{"id":"2c3cf6a2-64ff-41fd-9f0f-43eec43b3ff5","enquiry_id":"83cc054f-e372-49be-adc5-ef01bd87360a","source":"audio","audio_url":null,"raw_text":"Front Desk: Good afternoon, Aangan Studio.\nCaller: Hello, I saw your work on LinkedIn. My name is Suresh Patil. I’m in Nashik — would you be able to take on a project here? I want to redo my home office and study.\nFront Desk: Thank you for calling. We only work in Pune and PCMC at the moment — we don’t have the vendor network to take on projects outside Pune.\nCaller: Not even for a smaller project?\nFront Desk: Even for a smaller project, our execution depends on our contractors being on-site. I’m sorry we can’t help.\nCaller: Alright, understood. Thanks.","processed_text":null,"language":"en","durat