sage — happy to schedule a consultation.\n[No reply]\nStatus: Early-stage interest, no commitment. Re-engage in 4–6 weeks.","processed_text":null,"language":"en","duration_seconds":null,"transcription_confidence":0.96,"field_confidence":{},"ambiguity_flags":[],"extraction":{"client_name":"Vivek Rao","client_phone":null,"client_email":null,"intent":"new_project","project_type":"residential","scope_type":"full_home","scope_summary":null,"scope_clarity":"not_stated","location":"Hinjewadi, PCMC","location_clarity":"clear","in_service_area":true,"area_sqft":null,"style_preferences":[],"timeline_text":null,"weeks_to_completion":null,"budget_low_inr":null,"budget_high_inr":null,"budget_flexibility":"unknown","referral_source":null,"founder_connection":false,"asked_for_pricing":false,"competitive":false,"custom_work_flags":[],"criteria":{"real_project":"fail","service_area":"pass","timeline":"unclear","budget":"unclear","decision_maker":"unclear"},"criteria_notes":{"real_project":"Said \"still early stage — just exploring\"; asked only for a portfolio."},"clarifying_question":null,"summary":"Vivek Rao has a 3BHK in Hinjewadi but is only exploring and asked for a portfolio. No commitment. Nurture: re-engage in 4–6 weeks.","sentiment":"neutral","ambiguity_flags":[],"field_confidence":{},"transcription_confidence":0.96,"inaudible_count":0},"model":"gemini-3.8-flash","input_tokens":1040,"output_tokens":750,"ai_cost_inr":0.1925,"created_at":"2026-09-22T12:43:00.000Z"},{"id":"f95608b7-bc0f-4f64-b617-e7a2b87f8002","enquiry_id":"89a2c583-1afe-4078-929f-c69f87461619","source":"form","audio_url":null,"raw_text":"Name: Sumit Bhatt\nPhone: [redacted]  Email: [redacted]\nProject type: Residential — Full home\nLocation: Kalyani Nagar, Pune\nCarpet area: ~920 sq ft (2BHK)\nCurrent state: Moved in 8 months ago with basic furniture. Want to redo the kitchen (modular), both bedrooms (wardrobes, storage, beds), living room, and add a home office corner.\nTimeline: Execution starting December,